DECLARE
  l_existing_dept      employees.department_id%TYPE;
  l_no_match_dept      employees.department_id%TYPE := -1;
  l_existing_count     NUMBER;
  l_expected_existing  NUMBER;
  l_actual_existing    NUMBER;
  l_no_match_rows      NUMBER;
  l_expected_no_match  NUMBER;
  l_actual_no_match    NUMBER;
  l_expected_null      NUMBER := 0;
  l_actual_null        NUMBER;
  l_failures           NUMBER := 0;
BEGIN
  SAVEPOINT test_savepoint;

  -- Check 1: existing non-NULL department_id.
  SELECT MIN(department_id)
    INTO l_existing_dept
    FROM employees;

  IF l_existing_dept IS NULL THEN
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: existing-row setup: expected a non-NULL employees.department_id, actual: none found'
    );
    l_failures := l_failures + 1;
  ELSE
    SELECT COUNT(*)
      INTO l_expected_existing
      FROM employees
     WHERE department_id = l_existing_dept;

    l_actual_existing := HARNESS_APP.headcount(l_existing_dept);

    IF l_actual_existing = l_expected_existing THEN
      DBMS_OUTPUT.PUT_LINE(
        'PASS: existing department_id=' || l_existing_dept ||
        ', expected=' || l_expected_existing ||
        ', actual=' || l_actual_existing
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: existing department_id=' || l_existing_dept ||
        ', expected=' || l_expected_existing ||
        ', actual=' || l_actual_existing
      );
      l_failures := l_failures + 1;
    END IF;
  END IF;

  -- Check 2: non-NULL value that matches no row.
  SELECT COUNT(*)
    INTO l_no_match_rows
    FROM employees
   WHERE department_id = l_no_match_dept;

  IF l_no_match_rows <> 0 THEN
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: non-NULL no-match setup: expected COUNT(*) = 0 for department_id=' ||
      l_no_match_dept || ', actual=' || l_no_match_rows
    );
    l_failures := l_failures + 1;
  ELSE
    l_expected_no_match := 0;
    l_actual_no_match := HARNESS_APP.headcount(l_no_match_dept);

    IF l_actual_no_match = l_expected_no_match THEN
      DBMS_OUTPUT.PUT_LINE(
        'PASS: non-NULL no-match department_id=' || l_no_match_dept ||
        ', expected=' || l_expected_no_match ||
        ', actual=' || l_actual_no_match
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: non-NULL no-match department_id=' || l_no_match_dept ||
        ', expected=' || l_expected_no_match ||
        ', actual=' || l_actual_no_match
      );
      l_failures := l_failures + 1;
    END IF;
  END IF;

  -- Check 3: NULL argument. The function uses equality, so NULL matches no rows.
  l_actual_null := HARNESS_APP.headcount(NULL);

  IF l_actual_null = l_expected_null THEN
    DBMS_OUTPUT.PUT_LINE(
      'PASS: NULL department_id, expected=' || l_expected_null ||
      ', actual=' || l_actual_null
    );
  ELSE
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: NULL department_id, expected=' || l_expected_null ||
      ', actual=' || l_actual_null
    );
    l_failures := l_failures + 1;
  END IF;

  ROLLBACK TO test_savepoint;

  IF l_failures > 0 THEN
    RAISE_APPLICATION_ERROR(
      -20001,
      'headcount tests failed: ' || l_failures
    );
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error: ' || SQLERRM);
    ROLLBACK TO test_savepoint;
    RAISE;
END;
```

The first check selects a non-NULL `employees.department_id`, computes the expected count independently with `COUNT(*)`, calls `HARNESS_APP.headcount` for that value, and compares the result. If no suitable row exists, it prints `FAIL` and counts as a failure.

The second check uses `-1` as a candidate non-NULL value that should match no rows, confirms that assumption with `COUNT(*)`, then calls `HARNESS_APP.headcount(-1)` and expects `0`. If `-1` is not actually absent from `employees.department_id`, the setup check prints `FAIL` and counts as a failure.

The third check passes `NULL` to `headcount`. Because the function uses `department_id = p_department_id`, a `NULL` argument matches no rows, so the expected result is `0`, not a count of rows where `department_id IS NULL`.

The block starts with a `SAVEPOINT`, rolls back to it at the end, and also rolls back to it and re-raises if an unexpected exception occurs. It does not commit. I have not run this block.

